@startuml

class Well {
  + code : string
}

abstract class OnshoreWell extends Well {
  + surfaceExtension : float
}

abstract class OffshoreWell extends Well {
  + installationYear : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

OnshoreWell "1" -- "*" Extraction
OffshoreWell "1" -- "*" Extraction
OilCompany "1" -- "*" Extraction

Extraction "*" -- "1" Well
Extraction "*" -- "1" OilCompany

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

